mapper.select:
select p.id, p.code, p.post_name, p.sort, p.status, p.create_time, p.create_by, p.update_time, p.update_by
from sys_post p
where p.del_flag = 0

    and p.code like concat('%', #{req.code}, '%')


    and p.post_name like concat('%', #{req.postName}, '%')


    and p.status = #{req.status}


    and p.create_time >= #{req.startCreateTime}


    and p.create_time <= #{req.endCreateTime}

order by p.sort
